<?php $historyPage = max(1,(int)($_GET['p'] ?? 1)); $offset = ($historyPage-1)*50; $entries = query('SELECT a.*,u.name FROM app_audit a LEFT JOIN mainuser_acc u ON u.user_id = a.user_id ORDER BY a.id DESC LIMIT 50 OFFSET ' . $offset)->fetchAll(); $totalEntries = (int)query('SELECT COUNT(*) FROM app_audit')->fetchColumn(); ?>
<div class="page-heading"><div><span class="eyebrow">Accountability</span><h1>Activity history</h1><p class="muted">Sign-ins, changes, reviews, archives, and exports in the upgraded application. Times use Asia/Manila.</p></div></div>
<section class="card"><div class="table-scroll"><table><caption class="sr-only">Application audit history</caption><thead><tr><th scope="col">When</th><th scope="col">Person</th><th scope="col">Action</th><th scope="col">Resource</th><th scope="col">Record</th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr><td><?= e($entry['created_at']) ?></td><td><?= e($entry['name'] ?: 'Public registration') ?></td><td><?= e(label($entry['action'])) ?></td><td><?= e($entry['resource']) ?></td><td><?= e($entry['record_id'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$entries): ?><?= empty_state('No activity recorded','New actions appear here automatically.') ?><?php endif; ?><nav class="pagination" aria-label="History pages"><?php if ($historyPage>1): ?><?= button('Previous',['href'=>url('history',['p'=>$historyPage-1]),'variant'=>'secondary']) ?><?php endif; ?><span>Page <?= $historyPage ?></span><?php if ($historyPage*50<$totalEntries): ?><?= button('Next',['href'=>url('history',['p'=>$historyPage+1]),'variant'=>'secondary']) ?><?php endif; ?></nav></section>
<section class="card review-card"><h2>Preserved sign-in history</h2><div class="table-scroll"><table><caption class="sr-only">Legacy and current sign-in history</caption><thead><tr><th scope="col">Username</th><th scope="col">Sign-in time</th></tr></thead><tbody><?php foreach (query('SELECT username,datetime FROM loghistory ORDER BY log_id DESC LIMIT 50')->fetchAll() as $entry): ?><tr><td><?= e($entry['username']) ?></td><td><?= e($entry['datetime']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
